-- PT101-S3-Q16. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT101-S3-Q16$batch12$ AND q.stimulus=$batch12$K, a research scientist, was accused of having falsified laboratory data. Although the original data in question have disappeared, data from K’s more recent experiments have been examined and clearly none of them were falsified. Therefore, the accusation should be dismissed.$batch12$ AND q.prompt=$batch12$Which one of the following contains questionable reasoning that is most similar to that in the argument above?$batch12$ AND q.correct_choice=$batch12$A$batch12$) THEN RAISE EXCEPTION 'Question changed: PT101-S3-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT101-S3-Q16$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S3-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT101-S3-Q16$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The accusation that K falsified data should be dismissed.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$The data in question are gone. K's more recent data were checked and none were falsified.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The accusation is about the missing data. The evidence is about different, later data. Clean later work doesn't show the earlier work was clean. The flaw: dismiss a charge about one set of records using other records.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Find an argument that dismisses a charge about lost records using evidence from different records.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT101-S3-Q16$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$The records that matter were destroyed, so L's current clients' clean records are used to dismiss the charge. Same move.$batch12$), ($batch12$B$batch12$, $batch12$This concludes the charge should be discussed, not dismissed, and the evidence actually supports the charge.$batch12$), ($batch12$C$batch12$, $batch12$The other work came after N's, so N couldn't have copied it. That is a real defense based on the evidence at issue.$batch12$), ($batch12$D$batch12$, $batch12$This supports the accusation instead of dismissing it.$batch12$), ($batch12$E$batch12$, $batch12$This relies on disagreement about the public interest, not on evidence from unrelated records.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT101-S3-Q16$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
